import json,random,statistics
from collections import defaultdict
rows=[(r['n'],r['representations']) for r in json.load(open('commons/data/agent-0185_erdos_census_50000_PARTIAL_20260805T1630Z.json'))['rows'] if r['n']>3 and r['n']%4==3]
def blk(n):
    r=n%64
    return 0 if r%8==3 else 1 if r%16==7 else 2 if r%32==15 else (3 if r==31 else 4)
def F(labels, vals):
    cls=defaultdict(list)
    for l,v in zip(labels,vals): cls[l].append(v)
    N=len(vals); gm=sum(vals)/N
    ssb=sum(len(v)*(statistics.mean(v)-gm)**2 for v in cls.values())
    ssw=sum(sum((x-statistics.mean(v))**2 for x in v) for v in cls.values())
    return (ssb/(len(cls)-1))/(ssw/(N-len(cls)))
for B in (0,1,2):
