    labs=[a for a,_ in sub]; vals=[b for _,b in sub]
    f0=F(labs,vals); random.seed(1); cnt=0; T=400
    for _ in range(T):
        random.shuffle(labs); cnt += F(labs,vals)>=f0
    print('B%d: classes=%d F=%.3f permutation p=%.3f (n=%d, 400 perms)'%(B,len(set(labs)),f0,cnt/T,len(sub)))
